"""Generated bytes, packaged paths, and the declared illustrative results."""

import ast
from pathlib import Path

from arci.logs.example import load
from arci.logs.records import render_model
from bench.make_log_example import ROOT, generate, main
from tests.unit.logs.test_report import example_record


def test_generated_bytes_and_result() -> None:
    assert main(["--check"]) == 0
    assert generate() == generate()
    assert sum(map(len, generate().values())) < 400_000
    decision = example_record()
    assert [(t.result, t.model, t.effort) for t in decision.tools] == [
        ("REAL_DROP", "model-1", "high"),
        ("NO_DROP", "model-1", "high"),
    ]
    assert decision.exit_code == 1
    for tool in decision.tools:
        assert len(tool.measures[0].before_days) == 42
        assert len(tool.measures[0].after_days) == 14
        assert all(day.count == 17 for day in tool.measures[0].before_days)
        for measure in tool.measures:
            assert len(measure.before_days) == 42
            assert len(measure.after_days) == 14
            assert measure.finding != "too_few_days"
        assert tool.measures[1].median_before == tool.measures[1].median_after == "3/20"
        if tool.tool == "claude-code":
            assert tool.measures[2].median_before == tool.measures[2].median_after == "1/10"
            assert all(day.count >= 10 for day in tool.measures[2].before_days)
        else:
            assert tool.measures[2].median_before == tool.measures[2].median_after == "2/17"
    assert render_model("claude-example-1") is None
    assert render_model("codex-example-1") is None
    a, b, instant = load()
    assert a.parent == b.parent == ROOT
    assert instant.isoformat() == "2026-11-15T00:00:00+00:00"


def test_logs_dispatch_is_lazy_in_source() -> None:
    tree = ast.parse(Path("src/arci/cli.py").read_text())
    imports = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.ImportFrom) and (node.module or "").startswith("arci.logs")
    ]
    assert len(imports) == 1
    main_fn = next(
        node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == "main"
    )
    branches = [
        node
        for node in ast.walk(main_fn)
        if isinstance(node, ast.If) and "arguments[0] == 'logs'" in ast.unparse(node.test)
    ]
    assert len(branches) == 1
    assert imports[0] in branches[0].body
